class ReverseIdCacheTest {

	private static final SimpleValueFactory VALUES = SimpleValueFactory.getInstance();
	private static final ReverseIdCache.KeyAdapter<RdfTermKey, Value> KEYS = new ReverseIdCache.KeyAdapter<>() {
		@Override
		public int hash(Value value) {
			return RdfTermKey.spellingHash(value);
		}

		@Override
		public int keyHash(RdfTermKey key) {
			return key.spellingHash();
		}

		@Override
		public boolean matches(RdfTermKey key, Value value) {
			return key.matches(value);
		}

		@Override
		public RdfTermKey snapshot(Value value) {
			return RdfTermKey.of(value);
		}

		@Override
		public long lexicalLength(RdfTermKey key) {
			return key.lexicalLength();
		}
	};

	@Test
	void hashCollisionsNeverReturnAnotherValuesId() {
		ReverseIdCache<RdfTermKey, Value> cache = new ReverseIdCache<>(4, false, 1024, KEYS);
		Value first = VALUES.createBNode("Aa");
		Value second = VALUES.createBNode("BB");
		assertEquals(RdfTermKey.spellingHash(first), RdfTermKey.spellingHash(second));
		var state = cache.state();
		cache.put(state, RdfTermKey.of(first), 1, null, null, 0);
		cache.put(state, RdfTermKey.of(second), -1, null, new Object(), 0);
		assertEquals(1, cache.get(state, VALUES.createBNode("Aa"), 0).id());
		assertEquals(-1, cache.get(state, VALUES.createBNode("BB"), 0).id());
		assertNull(cache.get(state, VALUES.createBNode("AaAa"), 0));
	}

	@Test
	void clearDoesNotAllowAnOldLoadToPopulateTheNewState() {
		ReverseIdCache<RdfTermKey, Value> cache = new ReverseIdCache<>(16, false, 1024, KEYS);
		var previous = cache.state();
		Value value = VALUES.createBNode("delayed");
		cache.clear();
		cache.put(previous, RdfTermKey.of(value), -1, null, new Object(), 0);
		assertNull(cache.get(cache.state(), value, 0));
	}

	@Test
	void boundedCollisionChurnEvictsOnlyTheOldEntries() {
		ReverseIdCache<RdfTermKey, Value> cache = new ReverseIdCache<>(4, false, 1024, KEYS);
		var state = cache.state();
		String[] labels = { "AaAaAa", "AaAaBB", "AaBBAa", "AaBBBB", "BBAaAa", "BBAaBB", "BBBBAa", "BBBBBB" };
		int hash = RdfTermKey.spellingHash(VALUES.createBNode(labels[0]));
		for (int i = 0; i < labels.length; i++) {
			Value value = VALUES.createBNode(labels[i]);
			assertEquals(hash, RdfTermKey.spellingHash(value));
			cache.put(state, RdfTermKey.of(value), i % 2 == 0 ? i : -1, null, new Object(), 0);
		}
		assertEquals(4, cache.capacity());
		for (int i = 0; i < labels.length; i++) {
			var entry = cache.get(state, VALUES.createBNode(labels[i]), 0);
			if (i < 4) {
				assertNull(entry, "bounded churn must evict the older collision");
			} else {
				assertNotNull(entry);
				assertEquals(i % 2 == 0 ? i : -1, entry.id());
			}
		}
	}

	@Test
	void oversizedKeysBypassPositiveAndNegativeAdmission() {
		ReverseIdCache<RdfTermKey, Value> cache = new ReverseIdCache<>(16, false, 3, KEYS);
		var state = cache.state();
		Value value = VALUES.createBNode("long");
		cache.put(state, RdfTermKey.of(value), 12, null, null, 0);
		assertNull(cache.get(state, value, 0));
		cache.put(state, RdfTermKey.of(value), -1, null, new Object(), 0);
		assertNull(cache.get(state, value, 0));
		Value shortValue = VALUES.createBNode("fit");
		cache.put(state, RdfTermKey.of(shortValue), 13, null, null, 0);
		assertNotNull(cache.get(state, shortValue, 0));
	}

	@Test
	void unboundedModeKeepsEveryBankIndependent() {
		ReverseIdCache<RdfTermKey, Value> cache = new ReverseIdCache<>(0, true, 1024, KEYS);
		var state = cache.state();
		for (int i = 0; i < 100; i++) {
			Value value = VALUES.createBNode("value-" + i);
			cache.put(state, RdfTermKey.of(value), i, null, null, ValuePosition.OBJECT);
		}
		for (int i = 0; i < 100; i++) {
			Value value = VALUES.createBNode("value-" + i);
			assertEquals(i, cache.get(state, value, ValuePosition.OBJECT).id());
			assertNull(cache.get(state, value, ValuePosition.SUBJECT));
			assertNull(cache.get(state, value, ValuePosition.NONE));
		}
	}

	@Test
	void namespacePrefixesAndOrdinaryKeysHaveSymmetricExactEquality() {
		String lexical = "urn:namespace:α:€:𐐀/😀x";
		byte[] utf8 = lexical.getBytes(StandardCharsets.UTF_8);
		for (int capacity : new int[] { 0, 32 }) {
			ReverseIdCache<NamespaceKey, Object> cache = new ReverseIdCache<>(capacity, false, 1024,
					NamespaceKey.KEYS);
			var state = cache.state();
			NamespaceKey.Prefix query = new NamespaceKey.Prefix(utf8, 1024);
			for (int length = utf8.length; length >= 0; length--) {
				if (length < utf8.length && (utf8[length] & 0xC0) == 0x80) {
					continue;
				}
				query.shorten(length);
				String namespace = new String(Arrays.copyOf(utf8, length), StandardCharsets.UTF_8);
				NamespaceKey ordinary = NamespaceKey.of(namespace);
				NamespaceKey prefix = query.retainedKey();
				assertEquals(ordinary, prefix);
				assertEquals(prefix, ordinary);
				assertEquals(namespace.hashCode(), prefix.hashCode());
				assertEquals(namespace.hashCode(), NamespaceKey.KEYS.hash(query));
				cache.put(state, prefix, -1, null, new Object(), 0);
				assertEquals(-1, cache.get(state, namespace, 0).id());
				cache.put(state, ordinary, length, null, null, 0);
				assertEquals(length, cache.get(state, query, 0).id());
			}
		}
	}

	@Test
	void retainedNamespacePrefixesShareOnlyCeilingBoundedBacking() {
		String lexical = "urn:namespace:very-long-tail";
		NamespaceKey.Prefix query = new NamespaceKey.Prefix(lexical.getBytes(StandardCharsets.UTF_8), 12);
		assertNull(query.retainedKey(), "an oversized prefix must bypass retention");
		query.shorten(12);
		NamespaceKey first = query.retainedKey();
		query.shorten(8);
		NamespaceKey second = query.retainedKey();
		assertSame(first.backing(), second.backing(), "one fallback must not copy each prefix spelling");
		assertEquals(12, first.backing().length(), "retained backing must obey the lexical ceiling itself");
		assertEquals(NamespaceKey.of(lexical.substring(0, 8)), second);
		ReverseIdCache<NamespaceKey, Object> cache = new ReverseIdCache<>(0, false, 12, NamespaceKey.KEYS);
		var state = cache.state();
		cache.put(state, NamespaceKey.of(lexical), 1, null, null, 0);
		assertNull(cache.get(state, lexical, 0));
		cache.put(state, second, 2, null, null, 0);
		assertEquals(2, cache.get(state, lexical.substring(0, 8), 0).id());
		NamespaceKey.Prefix unicode = new NamespaceKey.Prefix("α😀".getBytes(StandardCharsets.UTF_8), 12);
		assertThrows(IllegalArgumentException.class, () -> unicode.shorten(3));
		unicode.shorten(2);
		assertEquals(NamespaceKey.of("α"), unicode.retainedKey());
		assertThrows(IllegalArgumentException.class, () -> unicode.shorten(6));
	}

	@Test
	void namespacePrefixKeysRespectBoundedChurnUnboundedModeAndClear() {
		String[] namespaces = { "AaAaAa", "AaAaBB", "AaBBAa", "AaBBBB", "BBAaAa", "BBAaBB", "BBBBAa", "BBBBBB" };
		for (int capacity : new int[] { 0, 4 }) {
			ReverseIdCache<NamespaceKey, Object> cache = new ReverseIdCache<>(capacity, false, 1024,
					NamespaceKey.KEYS);
			var state = cache.state();
			for (int i = 0; i < namespaces.length; i++) {
				NamespaceKey.Prefix query = new NamespaceKey.Prefix(
						(namespaces[i] + "tail").getBytes(StandardCharsets.UTF_8), 1024);
				query.shorten(namespaces[i].length());
				cache.put(state, query.retainedKey(), i % 2 == 0 ? i : -1, null, new Object(), 0);
			}
			for (int i = 0; i < namespaces.length; i++) {
				var entry = cache.get(state, namespaces[i], 0);
				if (capacity != 0 && i < 4) {
					assertNull(entry);
				} else {
					assertNotNull(entry);
					assertEquals(i % 2 == 0 ? i : -1, entry.id());
				}
			}
			cache.clear();
			cache.put(state, NamespaceKey.of(namespaces[0]), 99, null, null, 0);
			assertNull(cache.get(cache.state(), namespaces[0], 0));
		}
	}

	@Test
	void namespaceProofPreservesPartialIntervalsSparseAnswersAndUnicodeBoundaries() {
		byte[] lexical = "urn:α😀/child".getBytes(StandardCharsets.UTF_8);
		Object scope = new Object();
		int[] lengths = { 11, 6 };
		long[] ids = { 17, 23 };
		NamespacePrefixProof proof = NamespacePrefixProof.copyOf(lexical, lexical.length, 5, lengths, ids, 2, scope);
		assertSame(scope, proof.scope());
		assertFalse(proof.covers(4), "an early successful lookup did not examine shorter namespaces");
		assertFalse(proof.covers(5), "a prefix cannot end in the middle of the two-byte alpha");
		assertTrue(proof.covers(6));
		assertEquals(23, proof.namespaceId(6));
		assertEquals(17, proof.namespaceId(11));
		assertEquals(-1, proof.namespaceId(10));
		assertThrows(IllegalArgumentException.class, () -> proof.namespaceId(4));
		assertEquals(6, proof.commonPrefixLength("urn:α😁/other".getBytes(StandardCharsets.UTF_8)),
				"shared UTF-8 leading bytes must not create a partial codepoint proof");
		lengths[1] = 4;
		ids[1] = 99;
		lexical[0] = 'x';
		assertEquals(23, proof.namespaceId(6), "proof answers must be immutable snapshots");
		assertEquals(11, proof.commonPrefixLength("urn:α😀/other".getBytes(StandardCharsets.UTF_8)));
		NamespaceKey.Prefix bounded = new NamespaceKey.Prefix("urn:😀/tail".getBytes(StandardCharsets.UTF_8), 5);
		assertEquals("urn:", bounded.retainedBacking(), "the retention ceiling must not split a surrogate pair");
		assertEquals(4, bounded.retainedByteLength());
	}
}
